head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.param1 = "";          // 발행기관 검색 팝업(ULDBNS25001) 검색어 — 팝업이 $p.parent().scwin.param1 로 읽는다(§6.4)
scwin.param2 = "";          // 발행기관 검색 팝업 보조 검색어(발행기관명) — 같은 계약의 param2
// 원본 : ULDBNS30400.gfm (채권 마감관리 > 채권처리현황)
/*
 * 화면 동작
 *  - 조건(기간·발행기관·종목·처리자·시장조치·처리구분·ESG채권·기준구분)으로 선택한 탭(전체·개별종목·일괄상장종목)의 목록만 조회한다.
 *  - 화면을 열면 "오늘 ~ 오늘" 로 전체 탭을 바로 조회한다(기간 검사 없이 — 원본과 같음).
 *  - 일괄상장종목 탭은 행을 옮길 때마다 아래 월별등록현황을 보여 준다(명세 없음 — TODO §10 #3).
 *  - 목록 행을 더블클릭하면 시장조치 구분별 종목 상세 팝업을 data 로 넘겨 연다.
 * 업무 분석 : conversion/gfm-front/ui/ULDBNS30400/ULDBNS30400.md (§번호는 이 문서의 절)
 */

// 처리구분 항목 — 전체·개별 탭 / 일괄상장종목 탭 (원본 cmb_BndStsGb cbdata · OnSelChanged 의 CBData — §7.1)
scwin.BND_STS_ITEMS = {
    normal : [["0", "전체"], ["1", "미처리"], ["2", "처리중"], ["3", "처리완료"], ["4", "반송"]],
    pack : [["0", "전체"], ["1", "미처리"], ["3", "접수완료"], ["4", "반송"]]
};

// 처리결과 글자색 class (원본 ColumnProp('PROC_STATE', 'color') decode — §6.9). base.css 공통 색상 class 만 쓴다(규칙 40) — 컬럼 customFormatter scwin.fmtProcState 가 this.setCellClass 로 붙인다(규칙 43).
// 미처리 #FF0000 → red, 반송 #0000FF → blue. 처리중·처리완료(#343434)는 기본 글자색이라 class 없음.
scwin.PROC_STATE_CLASS = {
    "미처리" : "red",
    "반송" : "blue"
};

// 일괄상장 시장조치코드 — 상세 팝업 코드에 "Y" 를 붙인다 (국채·지방채·특수채 일괄상장 → ULDBNS05202, §7.1)
scwin.PACK_MKTACT_CDS = ["112", "122", "132"];

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name scwin.onpageload
 * @author Inswave
 * @date 2026. 10. 27
 * @description 페이지로드. 로딩 로직은 scwin.init 하나에 둔다(code-convention 초기화 절). (§3)
 * @returns
 * @hidden N
 */
scwin.onpageload = async function () {
    try {
        await scwin.init();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDBNS30400.onpageload" });
    }
};

/**
 * @method
 * @name scwin.onpageunload
 * @author Inswave
 * @date 2026. 10. 27
 * @description 화면 언로드. 정리할 자원이 없다(원본에도 없음).
 * @returns
 * @hidden N
 */
scwin.onpageunload = function () {
};

/**
 * @method
 * @name scwin.init
 * @author Inswave
 * @date 2026. 10. 27
 * @description 로딩 — 시장조치 공통 코드 → 조건 기본값(오늘 ~ 오늘) → init 바인딩(규칙 22·37) → 전체 탭 초기 조회. (원본 gform onload — §3)
 * @returns
 * @hidden N
 */
scwin.init = async function () {
    // 1) 시장조치 공통 코드 (원본 fn_SetBnsComboToCode2 — 03057 = BND_MKTACT_TP_CD, 104·105·999·313·321 제외, 첫 항목 "전체")
    // TODO: 필터 열 이름(cdVal)·원본 라벨 "코드 코드명" 형식 확인 (§10 #10)
    await $c.data.setCommonCode([{
        code : "BND_MKTACT_TP_CD",
        compID : "cmb_MktStsGb",
        firstRow : ["", "전체"],
        filter : ["cdVal!=104,105,999,313,321"]
    }]);

    // 2) 조건 기본값 — 원본 최종값: 시작일 = 종료일 = 오늘(서버 현재일 §8 #3). 처리구분 전체, 기준구분 신청일기준, ESG 해제
    // TODO: 원본은 직전영업일(fn_getDate)을 시작일에 넣은 직후 오늘로 덮어써 결과는 늘 오늘 ~ 오늘이다.
    //       직전영업일 조회(scwin.searchPrevBzDd)는 부르지 않는다 — 의도가 직전영업일이면 여기서 await scwin.searchPrevBzDd() (§5.4, §8 #1, §10 #4)
    const today = $c.date.getServerDateTime("yyyyMMdd");
    dma_search.set("strtDd", today);
    dma_search.set("endDd", today);
    dma_search.set("state", "0");
    dma_search.set("ddTp", "1");
    dma_search.set("sriBndTpCd", "");

    // 3) init 바인딩 (1회) — 기간 쌍은 compareFromToDate 만(규칙 37), 조회 영역 Enter 키(규칙 22)
    $c.date.compareFromToDate(edt_SDate, edt_EDate, ["기간 시작일", "기간 종료일"]);
    $c.win.setEnterKeyEvent(tbl_search, scwin.btn_Search_onclick);

    // 4) 초기 조회 — 전체 탭(원본과 같이 기간 검사 없이)
    await scwin.search();
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name scwin.btn_Search_onclick
 * @author Inswave
 * @date 2026. 10. 27
 * @description 조회 버튼 클릭(조회 영역 Enter 키 포함) — 기간 검사 후 선택한 탭을 조회한다. (원본 btn_Search onclick — §4, §6.1)
 * @param {Object} e 이벤트 객체
 * @returns
 * @hidden N
 */
scwin.btn_Search_onclick = async function (e) {
    try {
        if (!await scwin.validateSearch()) return;
        await scwin.search();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDBNS30400.btn_Search_onclick" });
    }
};

/**
 * @method
 * @name scwin.img_CoSearch_onclick
 * @author Inswave
 * @date 2026. 10. 27
 * @description 발행기관 찾기(돋보기) 클릭 (원본 fn_ShowIsur — §6.4)
