 * @returns
 * @hidden N
 */
scwin.img_CoSearch_onclick = async function (e) {
    try {
        await scwin.openIsurPopup();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDBNS30400.img_CoSearch_onclick" });
    }
};

/**
 * @method
