 * @author Inswave
 * @date 2026. 10. 27
 * @description 종목 찾기(돋보기) 클릭 (원본 fn_GetParListBndIsu·fn_SetParListBndIsu + fn_PopListBndIsuSearch — §6.5)
 * @param {Object} e 이벤트 객체
 * @returns
 * @hidden N
 */
scwin.btn_ISU_CD_SEARCH_onclick = async function (e) {
    try {
        await scwin.openListBndIsuPopup();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDBNS30400.btn_ISU_CD_SEARCH_onclick" });
    }
};

/**
 * @method
 * @name scwin.txb_ISUR_CD_onblur
 * @author Inswave
 * @date 2026. 10. 27
 * @description 발행기관코드 포커스 이탈 — 코드가 비었으면 발행기관명을 지운다. (원본 txb_ISUR_CD onblur — §6.4)
 * @param {Object} e 이벤트 객체
 * @returns
 * @hidden N
 */
scwin.txb_ISUR_CD_onblur = async function (e) {
    try {
        if ($c.util.isEmpty(txb_ISUR_CD.getValue())) {
            txb_COM_NM.setValue("");
        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDBNS30400.txb_ISUR_CD_onblur" });
    }
};

/**
 * @method
 * @name scwin.txb_ISU_CD_onblur
