 * @param {Object} e 이벤트 객체
 * @returns
 * @hidden N
 */
scwin.txb_ISU_CD_onblur = async function (e) {
    try {
        if ($c.util.isEmpty(txb_ISU_CD.getValue())) {
            txb_ISU_NM.setValue("");
        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDBNS30400.txb_ISU_CD_onblur" });
    }
};

/**
 * @method
 * @name scwin.btn_Excel_onclick
 * @author Inswave
 * @date 2026. 10. 27
 * @description 엑셀다운로드 클릭 — 선택한 탭의 목록을 내려받는다. (원본 fn_ExcelDown — §6.7)
