};

/**
 * @method
 * @name scwin.btn_Excel3_onclick
 * @author Inswave
 * @date 2026. 10. 27
 * @description 월별등록현황 엑셀다운로드 클릭 (원본 fn_ExcelDown3 — §6.8)
