    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDBNS30400.btn_Excel3_onclick" });
    }
};

/**
 * @method
 * @name scwin.tab_Main_onchange
 * @author Inswave
 * @date 2026. 10. 27
 * @description 탭 전환 — 탭별 조건(처리구분 항목·종목 잠금·기준구분)을 적용한다. 조회는 하지 않는다. (원본 tab_Main OnSelChanged — §6.2)
 * @param {String} tabId 선택된 탭 id
 * @param {Number} index 선택된 탭 index
 * @returns
 * @hidden N
 */
scwin.tab_Main_onchange = async function (tabId, index) {
    try {
        await scwin.applyTabCondition(Number(tab_Main.getSelectedTabIndex()));
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDBNS30400.tab_Main_onchange" });
    }
};

/**
 * @method
 * @name scwin.chk_SRI_BND_TP_CD_onviewchange
 * @author Inswave
 * @date 2026. 10. 27
 * @description ESG채권 체크 변경 — 전체 탭이 아니면 안내 후 해제하고, 기준구분 잠금을 다시 정한다. (원본 chk_SRI_BND_TP_CD onclick — §6.3)
 * @param {Object} info 변경 정보
 * @returns
 * @hidden N
 */
scwin.chk_SRI_BND_TP_CD_onviewchange = async function (info) {
    try {
        if (chk_SRI_BND_TP_CD.getValue() === "Y" && Number(tab_Main.getSelectedTabIndex()) !== 0) {
            await $c.win.alert("[개별종목], [일괄상장종목] 탭은 ESG채권과 함께 사용 할 수 없습니다.");
            chk_SRI_BND_TP_CD.setValue("");
        }
        scwin.applyDdTpLock();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDBNS30400.chk_SRI_BND_TP_CD_onviewchange" });
    }
};

/**
 * @method
 * @name scwin.grd_List1_oncelldblclick
 * @author Inswave
 * @date 2026. 10. 27
 * @description 전체 목록 더블클릭 — 종목 상세 팝업. (원본 grd_List1 OnDblClick — §6.6)
 * @param {Number} row 행 index
 * @param {Number} col 컬럼 index
 * @param {String} colId 컬럼 id
 * @returns
 * @hidden N
 */
scwin.grd_List1_oncelldblclick = async function (row, col, colId) {
    try {
        await scwin.openIsuInfoPopup(dlt_searchTotList, row, 0);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDBNS30400.grd_List1_oncelldblclick" });
    }
};

