 * @description 개별종목 목록 더블클릭 — 종목 상세 팝업. (원본 grd_List2 OnDblClick — §6.6)
 * @param {Number} row 행 index
 * @param {Number} col 컬럼 index
 * @param {String} colId 컬럼 id
 * @returns
 * @hidden N
 */
scwin.grd_List2_oncelldblclick = async function (row, col, colId) {
    try {
        await scwin.openIsuInfoPopup(dlt_searchIndvdlIsuList, row, 1);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDBNS30400.grd_List2_oncelldblclick" });
    }
};

/**
 * @method
 * @name scwin.grd_List3_oncelldblclick
 * @author Inswave
 * @date 2026. 10. 27
 * @description 일괄상장종목 목록 더블클릭 — 종목 상세 팝업. (원본 grd_List3 OnDblClick — §6.6)
