 */
scwin.grd_List3_oncelldblclick = async function (row, col, colId) {
    try {
        await scwin.openIsuInfoPopup(dlt_searchPackListIsuList, row, 2);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDBNS30400.grd_List3_oncelldblclick" });
    }
};

/**
 * @method
 * @name scwin.grd_List3_onrowindexchange
 * @author Inswave
 * @date 2026. 10. 27
 * @description 일괄상장종목 목록 행 이동 — 선택 행의 월별등록현황을 보여 준다. (원본 dts_List3 OnRowPosChanged — §5.5)
 * @param {Number} row 새 행 index
 * @param {Number} oldRow 이전 행 index
 * @returns
 * @hidden N
 */
scwin.grd_List3_onrowindexchange = async function (row, oldRow) {
    try {
        if (row < 0) return;    // 재조회로 선택 행이 없어진 경우
        scwin.searchPackListIsuDtl(row);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDBNS30400.grd_List3_onrowindexchange" });
    }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name scwin.searchTotList
 * @author Inswave
 * @date 2026. 10. 27
 * @description 전체 탭 목록 조회 → 건수·처리결과 색. (원본 fn_Search1 + dts_List1 OnLoadCompleted/OnLoadError — §5.1)
 * @returns
 * @hidden N
 */
scwin.searchTotList = async function () {
    const sbmOptions = {
        id : "sbm_searchTotList",
        method : "get",
        action : "/api/bonds/clsAdm/procsStat/totList-select",
        ref : "",
        target : "dlt_searchTotList=body",
        gridview : "grd_List1",
        isProcessMsg : false
    };

    // TODO: 명세는 ref: dma_search 와 requestData 를 함께 적음 — requestData 로 보낸다고 가정 (§10 #1)
    // TODO: 원본 SCREN_ID·SCREN_PROCES_TP_CD 는 명세에 없어 보내지 않음 (§10 #8)
    const result = await $c.sbm.executeDynamic(sbmOptions, scwin.getSearchData());
    if (result?.skipped) return;    // 진행 중 조회가 있어 이번 호출은 건너뜀

    if (!result.responseJSON?.success) {
        await $c.win.alert($c.stf.getMessageParam("MSG-0002"));
        return;
    }
    $c.stf.fillGridHeaderTotalCnt(dlt_searchTotList.getRowCount(), panel_page1);
};

/**
 * @method
 * @name scwin.searchIndvdlIsuList
 * @author Inswave
 * @date 2026. 10. 27
 * @description 개별종목 탭 목록 조회 → 건수·처리결과 색. (원본 fn_Search2 + dts_List2 OnLoadCompleted/OnLoadError — §5.2)
 * @returns
 * @hidden N
 */
scwin.searchIndvdlIsuList = async function () {
    const sbmOptions = {
        id : "sbm_searchIndvdlIsuList",
        method : "get",
        action : "/api/bonds/clsAdm/procsStat/indvdlIsuList-select",
        ref : "",
        // 명세 submission target 의 dlt_searchIndvdlisuList(소문자 i)는 정의 id 로 맞춤 (§10 #2)
        target : "dlt_searchIndvdlIsuList=body",
        gridview : "grd_List2",
        isProcessMsg : false
    };

    // TODO: 원본은 이 탭에서 ESG(V_SRI_BND_TP_CD)를 보내지 않음 — 명세대로 9키 모두 보냄 (§10 #7)
    const result = await $c.sbm.executeDynamic(sbmOptions, scwin.getSearchData());
    if (result?.skipped) return;    // 진행 중 조회가 있어 이번 호출은 건너뜀

    if (!result.responseJSON?.success) {
        await $c.win.alert($c.stf.getMessageParam("MSG-0002"));
        return;
    }
    $c.stf.fillGridHeaderTotalCnt(dlt_searchIndvdlIsuList.getRowCount(), panel_page2);
};

/**
 * @method
 * @name scwin.searchPackListIsuList
 * @author Inswave
 * @date 2026. 10. 27
 * @description 일괄상장종목 탭 목록 조회 → 건수·처리결과 색 → 첫 행 월별등록현황. (원본 fn_Search3 + dts_List3 OnLoadCompleted/OnRowPosChanged — §5.3)
 * @returns
 * @hidden N
 */
scwin.searchPackListIsuList = async function () {
    const sbmOptions = {
        id : "sbm_searchPackListIsuList",
        method : "get",
        action : "/api/bonds/clsAdm/procsStat/packListIsuList-select",
        ref : "",
        target : "dlt_searchPackListIsuList=body",
        gridview : "grd_List3",
        isProcessMsg : false
    };

    // TODO: 원본은 이 탭에서 종목·ESG·기준구분을 보내지 않음 — 명세대로 9키 모두 보냄(탭 잠금으로 값은 고정) (§10 #7)
    const result = await $c.sbm.executeDynamic(sbmOptions, scwin.getSearchData());
    if (result?.skipped) return;    // 진행 중 조회가 있어 이번 호출은 건너뜀

    if (!result.responseJSON?.success) {
        // 이전 행 기준 월별등록현황이 남지 않게 비운다
        dlt_searchPackListIsuDtlList.removeAll();
        $c.stf.fillGridHeaderTotalCnt(0, panel_page4);
        await $c.win.alert($c.stf.getMessageParam("MSG-0002"));
        return;
    }
    $c.stf.fillGridHeaderTotalCnt(dlt_searchPackListIsuList.getRowCount(), panel_page3);

    // 원본은 데이터셋 로드 때 OnRowPosChanged 가 발화해 첫 행 월별등록현황을 조회했다 — gridView 는 로드 때 행 이벤트가 없어 직접 부른다.
    // 0건이면 조회 없이 월별등록현황을 비운다(§8 #15).
    if (dlt_searchPackListIsuList.getRowCount() > 0) {
        // TODO: setFocusedCell 이 onrowindexchange 를 발화해 두 번 부르는지 실측 (§10 #19)
        grd_List3.setFocusedCell(0, "procState");
        scwin.searchPackListIsuDtl(0);
    } else {
        dlt_searchPackListIsuDtlList.removeAll();
        $c.stf.fillGridHeaderTotalCnt(0, panel_page4);
    }
};

/**
 * @method
 * @name scwin.searchPrevBzDd
 * @author Inswave
 * @date 2026. 10. 27
 * @description 직전영업일 조회 → 시작일. 명세 대응으로 정의만 두고 지금은 부르지 않는다 — 원본은 결과를 곧바로 오늘로 덮어썼다. (원본 fn_getDate — §5.4)
 * @returns
 * @hidden N
 */
scwin.searchPrevBzDd = async function () {
    const sbmOptions = {
        id : "sbm_searchPrevBzDd",
        method : "get",
        action : "/api/bonds/clsAdm/procsStat/prevBzDd-select",
        ref : "",
        target : "dma_searchPrevBzDd=body",
        isProcessMsg : false
    };

    // TODO: 호출 여부(시작일 = 직전영업일 의도인지)와 서버가 주는 날이 원본 3행 CALND_DD 와 같은지 확인 (§10 #4)
    const result = await $c.sbm.executeDynamic(sbmOptions);
    if (result?.skipped) return;    // 진행 중 조회가 있어 이번 호출은 건너뜀

    // 실패하면 시작일은 오늘 그대로 둔다(§5.4).
    if (!result.responseJSON?.success) return;
    if ($c.util.isEmpty(dma_searchPrevBzDd.get("calndDd"))) return;

    dma_search.set("strtDd", dma_searchPrevBzDd.get("calndDd"));
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name scwin.searchPackListIsuDtl
 * @author Inswave
 * @date 2026. 10. 27
 * @description 일괄상장종목 행의 월별등록현황. 명세에 API 가 없어 지금은 서버를 부르지 않고 빈 목록·건수 0 으로 둔다. (원본 fn_SearchDetail(row) + dts_ListDet OnLoadCompleted — §5.5)
 * @param {Number} rowIndex 일괄상장종목 목록 행 index
 * @returns
 * @hidden N
 */
scwin.searchPackListIsuDtl = function (rowIndex) {
    dlt_searchPackListIsuDtlList.removeAll();

    // TODO: 월별등록현황 API 명세 없음 (§10 #3) — 명세를 받으면 이 함수를 async 로 바꾸고 아래처럼 조회한다.
    //       id "sbm_searchPackListIsuDtl", method "get", action 명세 경로, ref "", target "dlt_searchPackListIsuDtlList=body",
    //       gridview "grd_ListDetail", requestData { bndApplId : dlt_searchPackListIsuList.getCellData(rowIndex, "bndApplId") }(키 가정),
    //       중복 실행 { onDuplicate : "abort" }(마지막 행이 이김 §8 #15), 실패 시 MSG-0002 안내.
    $c.stf.fillGridHeaderTotalCnt(dlt_searchPackListIsuDtlList.getRowCount(), panel_page4);
};

/**
 * @method
 * @name scwin.search
 * @author Inswave
 * @date 2026. 10. 27
 * @description 선택한 탭의 목록만 조회한다(0 전체, 1 개별종목, 2 일괄상장종목). 다른 탭 목록은 그대로 둔다. (원본 fn_Search — §6.2, §8 #9)
 * @returns
 * @hidden N
 */
scwin.search = async function () {
    const idx = Number(tab_Main.getSelectedTabIndex());

    if (idx === 0) {
        await scwin.searchTotList();
    } else if (idx === 1) {
        await scwin.searchIndvdlIsuList();
    } else if (idx === 2) {
        await scwin.searchPackListIsuList();
    }
};

/**
 * @method
 * @name scwin.validateSearch
 * @author Inswave
 * @date 2026. 10. 27
 * @description 조회 기간 검사 — 시작·종료일 필수·날짜 형식(공통 검증) 후 선후 확인. (원본 compareFromToDate2(edt_SDate, edt_EDate) — §6.1)
 * @returns {Promise<Boolean>} 검사 통과 여부
 * @hidden N
 */
scwin.validateSearch = async function () {
    const options = {
        validateType : "alert",     // alert|mark|all
        checkType : "single",       // single|multi
        fields : {
            edt_SDate : { required : true, format : "date", name : "기간 시작일" },
            edt_EDate : { required : true, format : "date", name : "기간 종료일" }
        }
    };
    if (!await $c.validate.validateDataCollect(tbl_search, options)) return false;

    // 입력 중 선후는 init 의 compareFromToDate 가 막지만, 코드로 넣은 값까지 조회 시점에 한 번 더 본다.
    if (dma_search.get("strtDd") > dma_search.get("endDd")) {
        // TODO: 원본 compareFromToDate2 의 검사 항목·안내 문구 확인 (§10 #13)
        await $c.win.alert("[기간] 시작일이 종료일보다 늦습니다.");
        edt_SDate.focus();
        return false;
    }
    return true;
};

/**
 * @method
 * @name scwin.getSearchData
 * @author Inswave
 * @date 2026. 10. 27
 * @description 조회 요청 데이터 — dma_search 9키(명세 requestData). ESG 는 체크 Y / 미체크 N 으로 맞춘다. (§6.10)
 * isurNm·isuNm 에는 원본처럼 코드 입력란 값이 들어간다(§8 #6, §10 #5).
 * @returns {Object} 요청 데이터
 * @hidden N
 */
scwin.getSearchData = function () {
    const data = dma_search.getJSON();

    // TODO: checkboxgroup 미체크 값은 "" — 원본은 "N" 으로 보였다. 서버 기대값 확인 (§10 #6)
    data.sriBndTpCd = (data.sriBndTpCd === "Y") ? "Y" : "N";
    return data;
};

/**
 * @method
 * @name scwin.applyTabCondition
 * @author Inswave
 * @date 2026. 10. 27
 * @description 탭별 조회 조건 적용. ESG 체크 상태로 개별·일괄 탭을 고르면 안내 후 전체 탭으로 되돌린다.
 * 처리구분 항목 교체(첫 항목 선택), 일괄 탭은 종목 조건을 비우고 잠근 뒤 기준구분을 잠근다. (원본 tab_Main OnSelChanged — §6.2)
 * @param {Number} idx 탭 index (0 전체, 1 개별종목, 2 일괄상장종목)
 * @returns
 * @hidden N
 */
scwin.applyTabCondition = async function (idx) {
    if (idx !== 0 && chk_SRI_BND_TP_CD.getValue() === "Y") {
        await $c.win.alert("[개별종목], [일괄상장종목] 탭은 ESG채권과 함께 사용 할 수 없습니다.");
        tab_Main.setSelectedTabIndex(0);
        // TODO: setSelectedTabIndex 가 onchange 를 다시 발화하는지 실측 (§10 #18) — 발화해도 같은 결과라 전체 탭 조건을 직접 적용한다.
        await scwin.applyTabCondition(0);
        return;
    }

    const isPack = (idx === 2);

    // 처리구분 항목 교체 + 첫 항목("전체") 선택 — 원본 CBData + ResetData()
    // TODO: removeAll/addItem 동작 실측 (§10 #19)
    const items = isPack ? scwin.BND_STS_ITEMS.pack : scwin.BND_STS_ITEMS.normal;
    cmb_BndStsGb.removeAll();
    items.forEach(([value, label]) => cmb_BndStsGb.addItem(value, label));
    cmb_BndStsGb.setSelectedIndex(0);

    // 종목 조건 — 일괄 탭은 비우고 잠금(원본 이미지 교체는 setDisabled 비활성 스타일로 대신)
    if (isPack) {
        dma_search.set("isuNm", "");
        txb_ISU_NM.setValue("");
    }
    txb_ISU_CD.setDisabled(isPack);
    btn_ISU_CD_SEARCH.setDisabled(isPack);

    scwin.applyDdTpLock();
};

/**
 * @method
 * @name scwin.applyDdTpLock
 * @author Inswave
 * @date 2026. 10. 27
 * @description 기준구분 잠금 — ESG 체크이거나 일괄상장종목 탭이면 신청일기준("1") 고정·잠금, 아니면 해제.
 * 원본은 두 이벤트가 따로 잠금을 풀어 고정이 풀렸다 — 두 조건을 함께 본다(§6.3, §8 #10).
 * @returns
 * @hidden N
 */
scwin.applyDdTpLock = function () {
    const lock = (chk_SRI_BND_TP_CD.getValue() === "Y") || (Number(tab_Main.getSelectedTabIndex()) === 2);

    if (lock) {
        dma_search.set("ddTp", "1");
    }
    rdo_DD_TP.setDisabled(lock);
};

/**
 * @method
 * @name scwin.fmtProcState
 * @author Inswave
 * @date 2026. 10. 27
 * @description 처리결과 컬럼 customFormatter — 값은 그대로(순수 데이터) 돌려주고, 글자색은 그리드 내장 API 로 붙인다.
 * 미처리 red, 반송 blue(base.css), 처리중·처리완료는 기본색이라 class 를 뗀다. 셀을 그릴 때마다(조회·정렬·스크롤) 엔진이 부르므로
 * 반복문 없이 색이 행을 따라간다(전환 규칙 43). 동기 함수 — async 금지. (원본 ColumnProp('PROC_STATE', 'color') decode — §6.9)
 * @param {String} data 원본 값(처리결과 명)
 * @param {String} formattedData 표시 형식이 적용된 값
 * @param {Number} rowIndex 화면 행 번호 — setCellClass 에 그대로 넘긴다(엔진이 실제 행으로 바꾼다)
 * @param {Number} colIndex 컬럼 번호
 * @returns {String} 셀에 표시할 값(HTML 없음)
 * @hidden N
 */
scwin.fmtProcState = function (data, formattedData, rowIndex, colIndex) {
    const cls = scwin.PROC_STATE_CLASS[data];
    if (cls) {
        this.setCellClass(rowIndex, colIndex, cls);
    } else {
        this.removeCellClass(rowIndex, colIndex);     // 값이 바뀐 행에 이전 class 가 남지 않게
    }
    return formattedData;
};

/**
 * @method
 * @name scwin.openIsurPopup
 * @author Inswave
 * @date 2026. 10. 27
 * @description 발행기관 검색 팝업(ULDBNS25001)을 data 로 넘겨 열고, 선택 값을 발행기관코드·명에 채운다. (원본 fn_GetParIsurCd·fn_SetParIsurCd + fn_PopIsurSearch — §6.4)
 * pcc $c.bns.popIsurSearch 는 data 를 넘기지 않아 화면에서 직접 연다(URL·크기는 pcc 와 같게).
 * 25001 전환본은 부모 scwin.param1(검색어)·param2 를 읽으므로 그 값을 먼저 채운다.
 * @returns
 * @hidden N
 */
scwin.openIsurPopup = async function () {
    const data = { isurCd : txb_ISUR_CD.getValue() };        // 원본 fn_GetParIsurCd: arrPar[0].ISUR_CD
    const options = {
        id : "ULDBNS25001",
        type : "pageFramePopup",
        popupName : "발행기관 검색",
        modal : true,
        width : 400,
        height : 485
    };

    // 25001 전환본(stf-front)은 data 대신 부모의 scwin.param1/param2 를 읽고 { isurCd, isurNm } 를 돌려준다(호출 선례 ULDBNS25100).
    // data 는 25001 이 getParameter() 로 바뀌면 쓰도록 함께 넘긴다(§10 #11).
    scwin.param1 = txb_ISUR_CD.getValue();
    scwin.param2 = txb_COM_NM.getValue();
    const result = await $c.win.openPopup("/ui/bns/bnslistsrchl/ULDBNS25001.xml", options, data);

    // 취소·닫기(X)도 객체가 오므로 필요한 필드로 판정한다.
    if ($c.util.isEmpty(result?.isurCd)) return;

    // 원본 fn_SetParIsurCd: txb_ISUR_CD ← ISUR_CD, txb_COM_NM ← ISUR_NM
    dma_search.set("isurNm", result.isurCd);    // txb_ISUR_CD 바인딩 키 (명세 키 이름이 isurNm — §10 #5)
    txb_COM_NM.setValue(result.isurNm);
};

/**
 * @method
 * @name scwin.openListBndIsuPopup
 * @author Inswave
 * @date 2026. 10. 27
 * @description 상장채권종목 검색 팝업(ULDBNS25101)을 data 로 넘겨 열고, 선택 값을 종목코드·명에 채운다. (원본 fn_GetParListBndIsu·fn_SetParListBndIsu + fn_PopListBndIsuSearch — §6.5)
 * pcc $c.bns.popListBndIsuSearch 는 data 를 넘기지 않아 화면에서 직접 연다(URL·크기는 pcc 와 같게).
 * @returns
 * @hidden N
 */
scwin.openListBndIsuPopup = async function () {
    const data = {
        listTypeCd : "2",                      // 원본 LIST_TYPE_CD '2'
        isurNm : txb_ISUR_CD.getValue(),       // 원본 ISUR_NM ← 발행기관 "코드" 입력란 (§8 #6)
        isuNm : txb_ISU_CD.getValue()          // 원본 ISU_NM ← 종목 "코드" 입력란
    };
    const options = {
        id : "ULDBNS25101",
        type : "pageFramePopup",
        popupName : "상장채권종목 검색",
        modal : true,
        width : 650,
        height : 510
    };

    // TODO: 25101 은 아직 fn_GetPar 수신 — getParameter()/closePopup({ stdCd, isuNm, isurNm }) 전환 때 키 확정 (§10 #11)
    const result = await $c.win.openPopup("/ui/bns/bnslistsrchl/ULDBNS25101.xml", options, data);
    if ($c.util.isEmpty(result?.stdCd)) return;

    // 원본 fn_SetParListBndIsu: txb_ISU_CD ← STD_CD, txb_ISU_NM ← ISU_NM (ISUR_NM 은 쓰지 않음)
    dma_search.set("isuNm", result.stdCd);
    txb_ISU_NM.setValue(result.isuNm);
};

/**
 * @method
 * @name scwin.openIsuInfoPopup
 * @author Inswave
 * @date 2026. 10. 27
 * @description 목록 행의 시장조치 구분별 종목 상세 팝업을 연다. 일괄상장(112·122·132) 건은 코드에 "Y" 를 붙인다
 * (전체 탭은 검색구분명이 일괄상장종목인 행만, 일괄 탭은 항상, 개별 탭은 붙이지 않음). (원본 OnDblClick + vs_G_* + fn_GetCommonKey — §6.6)
 * @param {Object} dlt 목록 dataList
 * @param {Number} rowIndex 행 index
 * @param {Number} tabIdx 탭 index (0 전체, 1 개별종목, 2 일괄상장종목)
 * @returns
 * @hidden N
 */
scwin.openIsuInfoPopup = async function (dlt, rowIndex, tabIdx) {
    let mktCd = String(dlt.getCellData(rowIndex, "bndMktactTpCd") ?? "");

    const isPackRow = (tabIdx === 2) || (tabIdx === 0 && dlt.getCellData(rowIndex, "searchGbNm") === "일괄상장종목");
    if (isPackRow && scwin.PACK_MKTACT_CDS.includes(mktCd)) {
        mktCd = mktCd + "Y";
    }

    // 원본 fn_GetCommonKey 의 arrPar[0] (vs_G_* 전역) — 일괄 탭도 행의 발행기관코드를 넘긴다(§8 #4)
    const data = {
        bndApplId : dlt.getCellData(rowIndex, "bndApplId"),
        bndMktactTpCd : mktCd,
        bndMktactTpNm : dlt.getCellData(rowIndex, "mktNm"),
        bkbndTpCd : dlt.getCellData(rowIndex, "bkbndTpCd"),
        strtDd : String(dlt.getCellData(rowIndex, "aplDt") ?? "").replace(/-/g, ""),
        stdCd : dlt.getCellData(rowIndex, "isuCd"),
        isurCd : dlt.getCellData(rowIndex, "isurCd")
    };

    // TODO: pcc popClsProcesStatIsuInfo 는 아직 data 인자가 없어 팝업에 전달되지 않음 — pcc 에 data 인자 추가와
    //       하위 상세 화면(ULDBNS90006·90007·05202·90008~90030)의 getParameter() 수신 전환 필요 (§10 #12)
    await $c.bns.popClsProcesStatIsuInfo(mktCd, data);
};

/**
 * @method
 * @name scwin.excelDown
 * @author Inswave
 * @date 2026. 10. 27
 * @description 선택한 탭의 목록을 엑셀로 내려받는다. 0건 안내는 공통 함수가 한다. (원본 fn_ExcelDown — §6.7, doLogSave 삭제 §8 #18)
 * @returns
 * @hidden N
 */
scwin.excelDown = function () {
    // 탭 본문은 처음 선택될 때 그려질 수 있어(alwaysDraw 기본 false) 선택한 탭의 그리드만 id 로 찾는다.
    const targets = [
        { id : "grd_List1", name : "채권처리현황(전체)" },
        { id : "grd_List2", name : "채권처리현황(개별)" },
        { id : "grd_List3", name : "채권처리현황(일괄)" }
    ];
    const target = targets[Number(tab_Main.getSelectedTabIndex())];
    if (!target) return;
    const grd = $p.getComponentById(target.id);
    if ($c.util.isEmpty(grd)) return;

    // TODO: 원본 GridToOffice(…, 8, 0) 옵션(숨김 열 포함 여부 등) 확인 (§10 #17)
    $c.data.downloadGridViewExcel(grd, {
        // 파일명 {menuId}_{이름}_{yyyyMMddHHmmss}.xlsx (전환 규칙 42)
        fileName : $c.win.getProgramId() + "_" + target.name + "_" + $c.date.getServerDateTime("yyyyMMddHHmmss") + ".xlsx",
        sheetName : "sheet1"
    });
};

/**
 * @method
 * @name scwin.excelDownDtl
 * @author Inswave
 * @date 2026. 10. 27
 * @description 월별등록현황 목록을 엑셀로 내려받는다. 0건 안내는 공통 함수가 한다. (원본 fn_ExcelDown3 — §6.8)
 * @returns
 * @hidden N
 */
scwin.excelDownDtl = function () {
    $c.data.downloadGridViewExcel(grd_ListDetail, {
        // 파일명 {menuId}_{이름}_{yyyyMMddHHmmss}.xlsx (전환 규칙 42)
        fileName : $c.win.getProgramId() + "_채권처리현황(일괄월별)_" + $c.date.getServerDateTime("yyyyMMddHHmmss") + ".xlsx",
        sheetName : "sheet1"
    });
};
